package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen1Test {

    @Test
    public void testCreateNumber_Null() throws NumberFormatException {
        assertNull(NumberUtils.createNumber(null));
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_Blank() throws NumberFormatException {
        NumberUtils.createNumber("   ");
    }

    @Test
    public void testCreateNumber_DoubleDash() throws NumberFormatException {
        assertNull(NumberUtils.createNumber("--123"));
    }

    @Test
    public void testCreateNumber_Hex() throws NumberFormatException {
        // Assuming createInteger handles hex
        Number result = NumberUtils.createNumber("0x10");
        assertTrue(result instanceof Integer);
        assertEquals(16, ((Integer) result).intValue());

        Number negHex = NumberUtils.createNumber("-0x10");
        assertEquals(-16, ((Integer) negHex).intValue());
    }

    @Test
    public void testCreateNumber_IntegerTypes() throws NumberFormatException {
        // Integer
        assertTrue(NumberUtils.createNumber("123") instanceof Integer);
        assertEquals(123, NumberUtils.createNumber("123").intValue());

        // Long
        assertTrue(NumberUtils.createNumber("1234567890123") instanceof Long);

        // BigInteger
        String huge = "9223372036854775808"; // Long.MAX_VALUE + 1
        assertTrue(NumberUtils.createNumber(huge) instanceof BigInteger);
    }

    @Test
    public void testCreateNumber_DecimalTypes() throws NumberFormatException {
        // Float
        assertTrue(NumberUtils.createNumber("1.23f") instanceof Float);
        // Double
        assertTrue(NumberUtils.createNumber("1.23d") instanceof Double);
        // BigDecimal
        assertTrue(NumberUtils.createNumber("1.23") instanceof BigDecimal);
        // Scientific notation
        assertTrue(NumberUtils.createNumber("1.23e2") instanceof Double);
    }

    @Test
    public void testCreateNumber_Suffixes() throws NumberFormatException {
        // Long suffix L
        assertTrue(NumberUtils.createNumber("123L") instanceof Long);
        assertTrue(NumberUtils.createNumber("123l") instanceof Long);

        // BigInteger via Long suffix
        assertTrue(NumberUtils.createNumber("9223372036854775808L") instanceof BigInteger);

        // Float suffix F
        assertTrue(NumberUtils.createNumber("1.23F") instanceof Float);
        // Double suffix D
        assertTrue(NumberUtils.createNumber("1.23D") instanceof Double);
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_InvalidSuffix() throws NumberFormatException {
        NumberUtils.createNumber("123X");
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_InvalidExponentPos() throws NumberFormatException {
        // expPos < decPos logic
        NumberUtils.createNumber("1e.5"); 
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_InvalidCharAtEnd() throws NumberFormatException {
        // Test the logic where lastChar is not digit or '.' and not a valid suffix
        NumberUtils.createNumber("123a");
    }

    @Test
    public void testCreateNumber_AllZerosEdgeCase() throws NumberFormatException {
        // Test the logic: if (f.floatValue() == 0.0F && !allZeros)
        // If it's all zeros, it should return the float/double instead of falling through to BigDecimal
        Number zeroFloat = NumberUtils.createNumber("0.000f");
        assertTrue(zeroFloat instanceof Float);
        assertEquals(0.0f, zeroFloat.floatValue(), 0.0f);

        Number zeroDouble = NumberUtils.createNumber("0.000d");
        assertTrue(zeroDouble instanceof Double);
        assertEquals(0.0, zeroDouble.doubleValue(), 0.0);
    }

    @Test
    public void testCreateNumber_FloatPrecisionFallthrough() throws NumberFormatException {
        // A number that is too large for Float but fits in Double
        // This triggers the fallthrough from case 'f' to case 'd'
        String largeVal = "1e38f"; 
        Number result = NumberUtils.createNumber(largeVal);
        // Depending on implementation of createFloat/createDouble, 
        // it might return Double if Float becomes infinite.
        assertNotNull(result);
    }

    @Test
    public void testCreateNumber_ComplexScientific() throws NumberFormatException {
        // Test case where expPos is valid but last char is not digit
        // e.g., 1.2e3L
        Number res = NumberUtils.createNumber("1.2e3L");
        // The code handles 'L' suffix by checking if dec/exp are null. 
        // If dec/exp are present, it throws NumberFormatException.
        // Let's test a valid one: 123L (no dec, no exp)
        assertEquals(123L, NumberUtils.createNumber("123L").longValue());
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_InvalidLSuffix() throws NumberFormatException {
        // L suffix with decimal should fail according to the logic
        NumberUtils.createNumber("1.23L");
    }

    @Test
    public void testCreateNumber_NegativeLargeLong() throws NumberFormatException {
        Number res = NumberUtils.createNumber("-9223372036854775808");
        assertTrue(res instanceof BigInteger);
    }
}
